  CURLE_HTTP2_STREAM(92),

  /// 93 - an api function was called from inside a callback
  CURLE_RECURSIVE_API_CALL(93),

  /// 94 - an authentication function returned an error
  CURLE_AUTH_ERROR(94),

  /// 95 - An HTTP/3 layer problem
  CURLE_HTTP3(95),

  /// 96 - QUIC connection error
  CURLE_QUIC_CONNECT_ERROR(96),

  /// 97 - proxy handshake error
  CURLE_PROXY(97),

  /// 98 - client-side certificate required
  CURLE_SSL_CLIENTCERT(98),

  /// 99 - poll/select returned fatal error
  CURLE_UNRECOVERABLE_POLL(99),

  /// 100 - a value/data met its maximum
  CURLE_TOO_LARGE(100),

  /// 101 - ECH tried but failed
  CURLE_ECH_REQUIRED(101),

  /// never use!
  CURL_LAST(102);

  final int value;
  const CURLcode(this.value);

  static CURLcode fromValue(int value) => switch (value) {
    0 => CURLE_OK,
    1 => CURLE_UNSUPPORTED_PROTOCOL,
    2 => CURLE_FAILED_INIT,
