    88 => CURLE_CHUNK_FAILED,
    89 => CURLE_NO_CONNECTION_AVAILABLE,
    90 => CURLE_SSL_PINNEDPUBKEYNOTMATCH,
    91 => CURLE_SSL_INVALIDCERTSTATUS,
    92 => CURLE_HTTP2_STREAM,
    93 => CURLE_RECURSIVE_API_CALL,
    94 => CURLE_AUTH_ERROR,
