}

/// All CURLOPT_* values.
enum CURLoption {
  /// This is the FILE * or void * the regular output should be written to.
  CURLOPT_WRITEDATA(10001),

  /// The full URL to get/put
  CURLOPT_URL(10002),

  /// Port number to connect to, if other than default.
  CURLOPT_PORT(3),

  /// Name of proxy to use.
  CURLOPT_PROXY(10004),

  /// "user:password;options" to use when fetching.
  CURLOPT_USERPWD(10005),

  /// "user:password" to use with proxy.
  CURLOPT_PROXYUSERPWD(10006),

  /// Range to get, specified as an ASCII string.
  CURLOPT_RANGE(10007),

  /// Specified file stream to upload from (use as input):
  CURLOPT_READDATA(10009),

  /// Buffer to receive error messages in, must be at least CURL_ERROR_SIZE
  /// bytes big.
  CURLOPT_ERRORBUFFER(10010),

  /// Function that will be called to store the output (instead of fwrite). The
  /// parameters will use fwrite() syntax, make sure to follow them.
  CURLOPT_WRITEFUNCTION(20011),

  /// Function that will be called to read the input (instead of fread). The
  /// parameters will use fread() syntax, make sure to follow them.
  CURLOPT_READFUNCTION(20012),

  /// Time-out the read operation after this amount of seconds
  CURLOPT_TIMEOUT(13),

  /// If CURLOPT_READDATA is used, this can be used to inform libcurl about how
  /// large the file being sent really is. That allows better error checking and
  /// better verifies that the upload was successful. -1 means unknown size.
  CURLOPT_INFILESIZE(14),

  /// POST static input fields.
  CURLOPT_POSTFIELDS(10015),

  /// Set the referrer page (needed by some CGIs)
  CURLOPT_REFERER(10016),

  /// Set the FTP PORT string (interface name, named or numerical IP address)
  /// Use i.e '-' to use default address.
  CURLOPT_FTPPORT(10017),

  /// Set the User-Agent string (examined by some CGIs)
  CURLOPT_USERAGENT(10018),

  /// Set the "low speed limit"
  CURLOPT_LOW_SPEED_LIMIT(19),

  /// Set the "low speed time"
  CURLOPT_LOW_SPEED_TIME(20),

  /// Set the continuation offset.
  CURLOPT_RESUME_FROM(21),

  /// Set cookie in request:
  CURLOPT_COOKIE(10022),

  /// This points to a linked list of headers, struct curl_slist kind. This list
  /// is also used for RTSP (in spite of its name)
  CURLOPT_HTTPHEADER(10023),

  /// This points to a linked list of post entries, struct curl_httppost
  CURLOPT_HTTPPOST(10024),

  /// name of the file keeping your private SSL-certificate
  CURLOPT_SSLCERT(10025),

  /// password for the SSL or SSH private key
  CURLOPT_KEYPASSWD(10026),

  /// send TYPE parameter?
  CURLOPT_CRLF(27),

  /// send linked-list of QUOTE commands
  CURLOPT_QUOTE(10028),

  /// send FILE * or void * to store headers to, if you use a callback it is
  /// simply passed to the callback unmodified
  CURLOPT_HEADERDATA(10029),

  /// point to a file to read the initial cookies from, also enables "cookie
  /// awareness"
  CURLOPT_COOKIEFILE(10031),

  /// What version to specifically try to use. See CURL_SSLVERSION defines
  /// below.
  CURLOPT_SSLVERSION(32),

  /// What kind of HTTP time condition to use, see defines
  CURLOPT_TIMECONDITION(33),

  /// Time to use with the above condition. Specified in number of seconds since
  /// 1 Jan 1970
  CURLOPT_TIMEVALUE(34),

  /// Custom request, for customizing the get command like HTTP: DELETE, TRACE
  /// and others FTP: to use a different list command
  CURLOPT_CUSTOMREQUEST(10036),

  /// FILE handle to use instead of stderr
  CURLOPT_STDERR(10037),

  /// send linked-list of post-transfer QUOTE commands
  CURLOPT_POSTQUOTE(10039),

  /// talk a lot
  CURLOPT_VERBOSE(41),

  /// throw the header out too
  CURLOPT_HEADER(42),

  /// shut off the progress meter
  CURLOPT_NOPROGRESS(43),

  /// use HEAD to get http document
  CURLOPT_NOBODY(44),

  /// no output on http error codes >= 400
  CURLOPT_FAILONERROR(45),

  /// this is an upload
  CURLOPT_UPLOAD(46),

  /// HTTP POST method
  CURLOPT_POST(47),

  /// bare names when listing directories
  CURLOPT_DIRLISTONLY(48),

  /// Append instead of overwrite on upload!
  CURLOPT_APPEND(50),

  /// Specify whether to read the user+password from the .netrc or the URL. This
  /// must be one of the CURL_NETRC_* enums below.
  CURLOPT_NETRC(51),

  /// use Location: Luke!
  CURLOPT_FOLLOWLOCATION(52),

  /// transfer data in text/ASCII format
  CURLOPT_TRANSFERTEXT(53),

  /// HTTP PUT
  CURLOPT_PUT(54),

  /// DEPRECATED Function that will be called instead of the internal progress
  /// display function. This function should be defined as the
  /// curl_progress_callback prototype defines.
  CURLOPT_PROGRESSFUNCTION(20056),

  /// Data passed to the CURLOPT_PROGRESSFUNCTION and CURLOPT_XFERINFOFUNCTION
  /// callbacks
  CURLOPT_XFERINFODATA(10057),

  /// We want the referrer field set automatically when following locations
  CURLOPT_AUTOREFERER(58),

  /// Port of the proxy, can be set in the proxy string as well with:
  /// "[host]:[port]"
  CURLOPT_PROXYPORT(59),

  /// size of the POST input data, if strlen() is not good to use
  CURLOPT_POSTFIELDSIZE(60),

  /// tunnel non-http operations through an HTTP proxy
  CURLOPT_HTTPPROXYTUNNEL(61),

  /// Set the interface string to use as outgoing network interface
  CURLOPT_INTERFACE(10062),

  /// Set the krb4/5 security level, this also enables krb4/5 awareness. This is
  /// a string, 'clear', 'safe', 'confidential' or 'private'. If the string is
  /// set but does not match one of these, 'private' will be used.
  CURLOPT_KRBLEVEL(10063),

  /// Set if we should verify the peer in ssl handshake, set 1 to verify.
  CURLOPT_SSL_VERIFYPEER(64),

  /// The CApath or CAfile used to validate the peer certificate this option is
  /// used only if SSL_VERIFYPEER is true
  CURLOPT_CAINFO(10065),

  /// Maximum number of http redirects to follow
  CURLOPT_MAXREDIRS(68),

  /// Pass a long set to 1 to get the date of the requested document (if
  /// possible)! Pass a zero to shut it off.
  CURLOPT_FILETIME(69),

  /// This points to a linked list of telnet options
  CURLOPT_TELNETOPTIONS(10070),

  /// Max amount of cached alive connections
  CURLOPT_MAXCONNECTS(71),

  /// Set to explicitly use a new connection for the upcoming transfer. Do not
  /// use this unless you are absolutely sure of this, as it makes the operation
  /// slower and is less friendly for the network.
  CURLOPT_FRESH_CONNECT(74),

  /// Set to explicitly forbid the upcoming transfer's connection to be reused
  /// when done. Do not use this unless you are absolutely sure of this, as it
  /// makes the operation slower and is less friendly for the network.
  CURLOPT_FORBID_REUSE(75),

  /// Set to a filename that contains random data for libcurl to use to seed the
  /// random engine when doing SSL connects.
  CURLOPT_RANDOM_FILE(10076),

  /// Set to the Entropy Gathering Daemon socket pathname
  CURLOPT_EGDSOCKET(10077),

  /// Time-out connect operations after this amount of seconds, if connects are
  /// OK within this time, then fine... This only aborts the connect phase.
  CURLOPT_CONNECTTIMEOUT(78),

  /// Function that will be called to store headers (instead of fwrite). The
  /// parameters will use fwrite() syntax, make sure to follow them.
  CURLOPT_HEADERFUNCTION(20079),

  /// Set this to force the HTTP request to get back to GET. Only really usable
  /// if POST, PUT or a custom request have been used first.
  CURLOPT_HTTPGET(80),

  /// Set if we should verify the Common name from the peer certificate in ssl
  /// handshake, set 1 to check existence, 2 to ensure that it matches the
  /// provided hostname.
  CURLOPT_SSL_VERIFYHOST(81),

  /// Specify which filename to write all known cookies in after completed
  /// operation. Set filename to "-" (dash) to make it go to stdout.
  CURLOPT_COOKIEJAR(10082),

  /// Specify which TLS 1.2 (1.1, 1.0) ciphers to use
  CURLOPT_SSL_CIPHER_LIST(10083),

  /// Specify which HTTP version to use! This must be set to one of the
  /// CURL_HTTP_VERSION* enums set below.
  CURLOPT_HTTP_VERSION(84),

  /// Specifically switch on or off the FTP engine's use of the EPSV command. By
  /// default, that one will always be attempted before the more traditional
  /// PASV command.
  CURLOPT_FTP_USE_EPSV(85),

  /// type of the file keeping your SSL-certificate ("DER", "PEM", "ENG")
  CURLOPT_SSLCERTTYPE(10086),

  /// name of the file keeping your private SSL-key
  CURLOPT_SSLKEY(10087),

  /// type of the file keeping your private SSL-key ("DER", "PEM", "ENG")
  CURLOPT_SSLKEYTYPE(10088),

  /// crypto engine for the SSL-sub system
  CURLOPT_SSLENGINE(10089),

  /// set the crypto engine for the SSL-sub system as default the param has no
  /// meaning...
  CURLOPT_SSLENGINE_DEFAULT(90),

  /// Non-zero value means to use the global dns cache
  CURLOPT_DNS_USE_GLOBAL_CACHE(91),

  /// DNS cache timeout
  CURLOPT_DNS_CACHE_TIMEOUT(92),

  /// send linked-list of pre-transfer QUOTE commands
  CURLOPT_PREQUOTE(10093),

  /// set the debug function
  CURLOPT_DEBUGFUNCTION(20094),

  /// set the data for the debug function
  CURLOPT_DEBUGDATA(10095),

  /// mark this as start of a cookie session
  CURLOPT_COOKIESESSION(96),

  /// The CApath directory used to validate the peer certificate this option is
  /// used only if SSL_VERIFYPEER is true
  CURLOPT_CAPATH(10097),

  /// Instruct libcurl to use a smaller receive buffer
  CURLOPT_BUFFERSIZE(98),

  /// Instruct libcurl to not use any signal/alarm handlers, even when using
  /// timeouts. This option is useful for multi-threaded applications. See
