/// this is the set of status codes pass in to the callback
enum curl_khmatch {
  /// match
  CURLKHMATCH_OK(0),

  /// host found, key mismatch!
  CURLKHMATCH_MISMATCH(1),

  /// no matching host/key found
  CURLKHMATCH_MISSING(2),

  /// not for use, only a marker for last-in-list
  CURLKHMATCH_LAST(3);

  final int value;
  const curl_khmatch(this.value);

  static curl_khmatch fromValue(int value) => switch (value) {
    0 => CURLKHMATCH_OK,
    1 => CURLKHMATCH_MISMATCH,
    2 => CURLKHMATCH_MISSING,
    3 => CURLKHMATCH_LAST,
    _ => throw ArgumentError('Unknown value for curl_khmatch: $value'),
  };
}

enum curl_khtype {
  CURLKHTYPE_UNKNOWN(0),
  CURLKHTYPE_RSA1(1),
  CURLKHTYPE_RSA(2),
  CURLKHTYPE_DSS(3),
  CURLKHTYPE_ECDSA(4),
  CURLKHTYPE_ED25519(5);

  final int value;
  const curl_khtype(this.value);

  static curl_khtype fromValue(int value) => switch (value) {
    0 => CURLKHTYPE_UNKNOWN,
    1 => CURLKHTYPE_RSA1,
    2 => CURLKHTYPE_RSA,
    3 => CURLKHTYPE_DSS,
    4 => CURLKHTYPE_ECDSA,
    5 => CURLKHTYPE_ED25519,
    _ => throw ArgumentError('Unknown value for curl_khtype: $value'),
  };
}

typedef curl_read_callback =
    ffi.Pointer<
      ffi.NativeFunction<
        ffi.Size Function(
          ffi.Pointer<ffi.Char> buffer,
          ffi.Size size,
          ffi.Size nitems,
          ffi.Pointer<ffi.Void> instream,
        )
      >
    >;

/// linked-list structure for the CURLOPT_QUOTE option (and other)
final class curl_slist extends ffi.Struct {
  external ffi.Pointer<ffi.Char> data;

  external ffi.Pointer<curl_slist> next;

  static ffi.Pointer<curl_slist> $allocate(
    ffi.Allocator $allocator, {
    required ffi.Pointer<ffi.Char> data,
    required ffi.Pointer<curl_slist> next,
  }) => $allocator<curl_slist>()
    ..ref.data = data
    ..ref.next = next;
}

typedef curl_sshhostkeycallback =
    ffi.Pointer<
      ffi.NativeFunction<
        ffi.Int Function(
          ffi.Pointer<ffi.Void> clientp,
          ffi.Int keytype,
          ffi.Pointer<ffi.Char> key,
          ffi.Size keylen,
        )
      >
    >;

enum curl_usessl {
  /// not an option, never use
  CURLUSESSL_LAST(4);

  final int value;
  const curl_usessl(this.value);

  static curl_usessl fromValue(int value) => switch (value) {
    4 => CURLUSESSL_LAST,
    _ => throw ArgumentError('Unknown value for curl_usessl: $value'),
  };
}

typedef curl_write_callback =
    ffi.Pointer<
      ffi.NativeFunction<
        ffi.Size Function(
          ffi.Pointer<ffi.Char> buffer,
          ffi.Size size,
          ffi.Size nitems,
          ffi.Pointer<ffi.Void> outstream,
        )
      >
    >;
